diff --git a/src/cache.ts b/src/cache.ts
index 9fa8c53..2226ee4 100644
--- a/src/cache.ts
+++ b/src/cache.ts
@@ -1,20 +1,65 @@
+import { ensureDir } from "https://deno.land/std@0.208.0/fs/mod.ts";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

 const store = new Map<string, Entry>();
+const CACHE_DIR = ".session-cache";
+
+const getFilePath = (key: string): string => {
+  return `${CACHE_DIR}/${encodeURIComponent(key)}.json`;
+};

-export const put = (key: string, value: string, ttlMs: number): void => {
-  store.set(key, { value, expiresAt: Date.now() + ttlMs });
+const loadFromDisk = async (key: string): Promise<Entry | null> => {
+  try {
+    const path = getFilePath(key);
+    const data = await Deno.readTextFile(path);
+    return JSON.parse(data);
+  } catch {
+    return null;
+  }
 };

-export const get = (key: string): string | null => {
-  const entry = store.get(key);
+const saveToDisk = async (key: string, entry: Entry): Promise<void> => {
+  await ensureDir(CACHE_DIR);
+  const path = getFilePath(key);
+  await Deno.writeTextFile(path, JSON.stringify(entry));
+};
+
+const deleteFromDisk = async (key: string): Promise<void> => {
+  try {
+    const path = getFilePath(key);
+    await Deno.remove(path);
+  } catch {
+    // File doesn't exist, ignore
+  }
+};
+
+export const put = async (key: string, value: string, ttlMs: number): Promise<void> => {
+  const entry = { value, expiresAt: Date.now() + ttlMs };
+  store.set(key, entry);
+  await saveToDisk(key, entry);
+};
+
+export const get = async (key: string): Promise<string | null> => {
+  let entry = store.get(key);
+
+  if (entry === undefined) {
+    entry = await loadFromDisk(key);
+    if (entry !== null) {
+      store.set(key, entry);
+    }
+  }
+
   if (entry === undefined) return null;
+
   if (entry.expiresAt < Date.now()) {
     store.delete(key);
+    await deleteFromDisk(key);
     return null;
   }
+
   return entry.value;
 };
